const DAY_MINUTES = 24 * 60;
const DAY_HOURS = 24;

function validateMinuteIntervalSchedule(
  config,
  label = "interval schedule"
) {
  const errors = [];
  const intervalMinutes = config?.schedule_minutes;
  const offsetMinutes = config?.schedule_offset_minutes;
  if (
    !Number.isInteger(intervalMinutes) ||
    intervalMinutes < 1 ||
    intervalMinutes > DAY_MINUTES ||
    DAY_MINUTES % intervalMinutes !== 0
  ) {
    errors.push(
      `${label} schedule_minutes must be a positive divisor of ${DAY_MINUTES}`
    );
  }
  if (
    !Number.isInteger(offsetMinutes) ||
    offsetMinutes < 0 ||
    (Number.isInteger(intervalMinutes) && offsetMinutes >= intervalMinutes)
  ) {
    errors.push(
      `${label} schedule_offset_minutes must be from 0 through schedule_minutes - 1`
    );
  }
  return errors;
}

function minuteIntervalExecutionMinutes(
  config,
  label = "interval schedule"
) {
  const errors = validateMinuteIntervalSchedule(config, label);
  if (errors.length > 0) {
    throw new Error(`Invalid ${label}:\n- ${errors.join("\n- ")}`);
  }
  const minutes = [];
  for (
    let minute = config.schedule_offset_minutes;
    minute < DAY_MINUTES;
    minute += config.schedule_minutes
  ) {
    minutes.push(minute);
  }
  return minutes;
}

function minuteIntervalScheduleRules(
  config,
  label = "interval schedule"
) {
  const executionMinutes = minuteIntervalExecutionMinutes(config, label);
  const hoursByMinute = new Map();
  for (const executionMinute of executionMinutes) {
    const minute = executionMinute % 60;
    const hour = Math.floor(executionMinute / 60);
    if (!hoursByMinute.has(minute)) hoursByMinute.set(minute, []);
    hoursByMinute.get(minute).push(hour);
  }
  const minutesByHours = new Map();
  for (const [minute, hours] of hoursByMinute) {
    const key = hours.join(",");
    if (!minutesByHours.has(key)) {
      minutesByHours.set(key, { hours, minutes: [] });
    }
    minutesByHours.get(key).minutes.push(minute);
  }
  return [...minutesByHours.values()]
    .map(({ hours, minutes }) => ({
      firstExecutionMinute: Math.min(
        ...executionMinutes.filter(
          (executionMinute) =>
            minutes.includes(executionMinute % 60) &&
            hours.includes(Math.floor(executionMinute / 60))
        )
      ),
      rule: {
        field: "cronExpression",
        expression: `0 ${minutes
          .sort((left, right) => left - right)
          .join(",")} ${
          hours.length === DAY_HOURS ? "*" : hours.join(",")
        } * * *`
      }
    }))
    .sort(
      (left, right) =>
        left.firstExecutionMinute - right.firstExecutionMinute
    )
    .map(({ rule }) => rule);
}


function parseHttpUrl(value, { baseOrigin = "" } = {}) {
  let input = String(value ?? "").trim();
  if (!input) return null;

  if (input.startsWith("/")) {
    const base = parseHttpUrl(baseOrigin);
    if (!base) return null;
    input = `${base.protocol}//${base.hostname}${base.port ? `:${base.port}` : ""}${input}`;
  }

  if (/[\u0000-\u0020\u007f\\]/.test(input)) return null;
  const match = input.match(
    /^(https?):\/\/([^/?#]+)(\/[^?#]*)?(\?[^#]*)?(#.*)?$/i
  );
  if (!match) return null;

  const protocol = `${match[1].toLowerCase()}:`;
  const authority = match[2];
  if (!authority || authority.includes("@") || authority.includes("[")) return null;

  const colonIndex = authority.lastIndexOf(":");
  let hostname = authority;
  let port = "";
  if (colonIndex >= 0) {
    if (authority.indexOf(":") !== colonIndex) return null;
    hostname = authority.slice(0, colonIndex);
    port = authority.slice(colonIndex + 1);
    if (!/^\d{1,5}$/.test(port)) return null;
    const portNumber = Number(port);
    if (portNumber < 1 || portNumber > 65535) return null;
  }

  hostname = hostname.toLowerCase();
  if (
    hostname.length > 253 ||
    hostname.split(".").some(
      (label) =>
        !label ||
        label.length > 63 ||
        !/^[a-z0-9](?:[a-z0-9-]*[a-z0-9])?$/i.test(label)
    )
  ) {
    return null;
  }

  const pathname = match[3] || "/";
  const search = match[4] || "";
  const hash = match[5] || "";
  return {
    protocol,
    hostname,
    port,
    pathname,
    search,
    hash,
    username: "",
    password: "",
    href: `${protocol}//${hostname}${port ? `:${port}` : ""}${pathname}${search}${hash}`
  };
}

function normalizeCanonicalUrl(value) {
  const parsed = parseHttpUrl(value, {
    baseOrigin: "https://www.onlinejobs.ph"
  });
  if (!parsed) return "";
  if (parsed.port && parsed.port !== "443") return "";
  const hostname =
    parsed.hostname === "www.onlinejobs.ph"
      ? "onlinejobs.ph"
      : parsed.hostname;
  if (hostname !== "onlinejobs.ph") return "";
  const pathname = parsed.pathname.replace(/\/+/g, "/").replace(/\/$/, "");
  if (!/^\/jobseekers\/job\/[^/]+$/i.test(pathname)) return "";
  return `https://${hostname}${pathname}`;
}

function extractOnlineJobsId(url) {
  const canonicalUrl = normalizeCanonicalUrl(url);
  if (!canonicalUrl) return "";
  const match = canonicalUrl.match(/\/jobseekers\/job\/[^/]*?(\d+)$/i);
  return match?.[1] ?? "";
}

function canonicalJobId(record) {
  const source = String(record.source || "onlinejobs.ph").trim().toLowerCase();
  const sourceJobId = String(record.source_job_id || extractOnlineJobsId(record.canonical_url || record.job_url) || "").trim();
  if (sourceJobId) return `${source}:${sourceJobId}`;
  const canonicalUrl = normalizeCanonicalUrl(record.canonical_url || record.job_url);
  if (!canonicalUrl) return "";
  let hash = 2166136261;
  for (let index = 0; index < canonicalUrl.length; index += 1) {
    hash ^= canonicalUrl.charCodeAt(index);
    hash = Math.imul(hash, 16777619);
  }
  const digest = (hash >>> 0).toString(16).padStart(8, "0");
  return `${source}:url:${digest}`;
}

function stateGuard(record) {
  const canonicalId = String(record.canonical_job_id || canonicalJobId(record) || "");
  if (!canonicalId) return "";
  const state = [
    canonicalId,
    String(record.pipeline_status || ""),
    String(record.user_action || ""),
    String(record.record_version || ""),
    String(record.processing_stage || ""),
    String(record.processing_token || ""),
    String(record.generated_at || ""),
    String(record.alert_status || ""),
    String(record.outcome || ""),
    String(record.applied_at || ""),
    String(record.archived_at || ""),
    String(record.archive_reason || "")
  ].join("\u001f");
  let hash = 2166136261;
  for (let index = 0; index < state.length; index += 1) {
    hash ^= state.charCodeAt(index);
    hash = Math.imul(hash, 16777619);
  }
  return `${canonicalId}|${(hash >>> 0).toString(16).padStart(8, "0")}`;
}

function rankingPriorityValue(record) {
  if (
    typeof record?.opportunity_score === "number" &&
    Number.isFinite(record.opportunity_score)
  ) {
    return {
      value: record.opportunity_score,
      source: "opportunity_score"
    };
  }
  if (typeof record?.match_score === "number" && Number.isFinite(record.match_score)) {
    return {
      value: record.match_score,
      source: "legacy_match_score"
    };
  }
  return { value: 0, source: "missing" };
}

function compareRankingPriority(left, right) {
  const scoreOrder =
    rankingPriorityValue(right).value - rankingPriorityValue(left).value;
  if (scoreOrder !== 0) return scoreOrder;
  const confidenceOrder =
    ({ high: 3, medium: 2, low: 1 }[right.ranking_confidence] ?? 0) -
    ({ high: 3, medium: 2, low: 1 }[left.ranking_confidence] ?? 0);
  if (confidenceOrder !== 0) return confidenceOrder;
  const timestamp = (value) => {
    const parsed = Date.parse(value || "");
    return Number.isFinite(parsed) ? parsed : Number.NEGATIVE_INFINITY;
  };
  const rightPosted = timestamp(right.posted_at);
  const leftPosted = timestamp(left.posted_at);
  if (rightPosted !== leftPosted) return rightPosted - leftPosted;
  const rightCreated = timestamp(right.created_at);
  const leftCreated = timestamp(left.created_at);
  if (rightCreated !== leftCreated) return rightCreated - leftCreated;
  return String(left.canonical_job_id || "").localeCompare(
    String(right.canonical_job_id || "")
  );
}

function parseList(value) {
  if (Array.isArray(value)) return value.filter(Boolean);
  if (!value) return [];
  try {
    const parsed = JSON.parse(value);
    if (Array.isArray(parsed)) return parsed.filter(Boolean);
  } catch {
    // Legacy sheets may use comma-separated values.
  }
  return String(value)
    .split(",")
    .map((part) => part.trim())
    .filter(Boolean);
}

function parseJsonArray(value) {
  if (Array.isArray(value)) return value;
  if (!value) return [];
  try {
    const parsed = JSON.parse(value);
    return Array.isArray(parsed) ? parsed : value;
  } catch {
    return value;
  }
}

function normalizeRuleValue(value, rule) {
  if (!rule || value === "" || value === undefined || value === null) return value ?? "";
  if (rule.type === "number" || rule.type === "integer") {
    const numeric = Number(value);
    return Number.isFinite(numeric) ? numeric : value;
  }
  if (rule.type === "string") return String(value).trim();
  return value;
}

function mergeOutcomeEvents(...collections) {
  const events = new Map();
  for (const collection of collections) {
    if (!Array.isArray(collection)) continue;
    for (const event of collection) {
      if (!event || typeof event !== "object" || Array.isArray(event)) continue;
      const id = String(event.id || "").trim();
      if (!id || events.has(id)) continue;
      events.set(id, { ...event, id });
    }
  }
  const timestamp = (value) => {
    const parsed = Date.parse(value || "");
    return Number.isFinite(parsed) ? parsed : Number.POSITIVE_INFINITY;
  };
  return [...events.values()].sort(
    (left, right) =>
      timestamp(left.at) - timestamp(right.at) ||
      String(left.id).localeCompare(String(right.id))
  );
}

function normalizeLegacyRecord(input, schema, now = new Date().toISOString()) {
  const record = { ...input };
  for (const [legacy, canonical] of Object.entries(schema.legacy_header_mapping ?? {})) {
    if (record[canonical] === undefined && record[legacy] !== undefined) {
      record[canonical] = record[legacy];
    }
  }

  const legacyStatus = String(record.pipeline_status || "").trim().toLowerCase();
  record.pipeline_status =
    schema.legacy_status_mapping?.[legacyStatus] ||
    (schema.pipeline_statuses.includes(legacyStatus) ? legacyStatus : "new");
  record.source = String(record.source || "onlinejobs.ph").trim().toLowerCase();
  record.canonical_url = normalizeCanonicalUrl(record.canonical_url || record.job_url);
  record.source_job_id = String(record.source_job_id || extractOnlineJobsId(record.canonical_url) || "");
  record.canonical_job_id = String(record.canonical_job_id || canonicalJobId(record));
  for (const field of schema.string_list_fields ?? ["matched_keywords"]) {
    record[field] = parseList(record[field]);
  }
  for (const field of schema.json_array_fields ?? []) {
    record[field] = parseJsonArray(record[field]);
  }
  for (const [field, rule] of Object.entries(schema.field_rules ?? {})) {
    record[field] = normalizeRuleValue(record[field], rule);
  }
  record.attempt_count = Number.isFinite(Number(record.attempt_count))
    ? Number(record.attempt_count)
    : 0;
  record.record_version = Number.isInteger(Number(record.record_version)) && Number(record.record_version) > 0
    ? Number(record.record_version)
    : 1;
  record.alert_attempt_count = Number.isFinite(Number(record.alert_attempt_count))
    ? Number(record.alert_attempt_count)
    : 0;
  record.created_at = record.created_at || now;
  record.updated_at = record.updated_at || now;
  record.source_availability = record.source_availability || "active";
  record.profile_version =
    record.profile_version ||
    (schema.schema_version === 1 ? "legacy/unknown" : "");
  record.message_profile_version =
    record.message_profile_version ||
    (schema.schema_version === 1 && record.generated_message
      ? "legacy/unknown"
      : "");
  record.outcome = record.outcome || "";
  record.user_action = record.user_action || "";
  record.state_guard = record.state_guard || stateGuard(record);
  return record;
}

function validateRecordContract(record, schema) {
  const errors = [];
  const fields = new Set(schema?.fields ?? []);
  for (const [field, rule] of Object.entries(schema?.field_rules ?? {})) {
    if (!fields.has(field)) {
      errors.push(`field rule references unknown field: ${field}`);
      continue;
    }
    const value = record?.[field];
    const missing = value === "" || value === undefined || value === null;
    if (missing) {
      if (rule.nullable === false) errors.push(`${field} is required`);
      continue;
    }
    if (rule.type === "enum") {
      if (!rule.values?.includes(value)) errors.push(`${field} has unsupported value: ${value}`);
      continue;
    }
    if (rule.type === "string") {
      if (typeof value !== "string") {
        errors.push(`${field} must be a string`);
        continue;
      }
      if (
        rule.maximum_length !== undefined &&
        value.length > rule.maximum_length
      ) {
        errors.push(`${field} exceeds its maximum length`);
      }
      if (rule.pattern && !new RegExp(rule.pattern).test(value)) {
        errors.push(`${field} has an unsupported format`);
      }
      continue;
    }
    const numeric = typeof value === "number" ? value : Number.NaN;
    if (!Number.isFinite(numeric)) {
      errors.push(`${field} must be a ${rule.type}`);
      continue;
    }
    if (rule.type === "integer" && !Number.isInteger(numeric)) {
      errors.push(`${field} must be an integer`);
    }
    if (rule.minimum !== undefined && numeric < rule.minimum) {
      errors.push(`${field} must be at least ${rule.minimum}`);
    }
    if (rule.maximum !== undefined && numeric > rule.maximum) {
      errors.push(`${field} must be at most ${rule.maximum}`);
    }
  }
  for (const field of schema?.string_list_fields ?? []) {
    const value = record?.[field];
    if (value !== undefined && !Array.isArray(value)) errors.push(`${field} must be an array`);
  }
  for (const field of schema?.json_array_fields ?? []) {
    const value = record?.[field];
    if (value !== undefined && !Array.isArray(value)) errors.push(`${field} must be a JSON array`);
  }
  if (Array.isArray(record?.outcome_events)) {
    const seen = new Set();
    const allowedTypes = new Set([
      "no_response",
      "replied",
      "interview",
      "offer",
      "rejected",
      "correction"
    ]);
    for (const [index, event] of record.outcome_events.entries()) {
      if (!event || typeof event !== "object" || Array.isArray(event)) {
        errors.push(`outcome_events[${index}] must be an object`);
        continue;
      }
      const id = String(event.id || "");
      if (!id || id.length > 256) {
        errors.push(`outcome_events[${index}].id is invalid`);
      } else if (seen.has(id)) {
        errors.push(`outcome_events contains duplicate id: ${id}`);
      } else {
        seen.add(id);
      }
      if (!allowedTypes.has(event.type)) {
        errors.push(`outcome_events[${index}].type is invalid`);
      }
      if (
        typeof event.at !== "string" ||
        !Number.isFinite(Date.parse(event.at))
      ) {
        errors.push(`outcome_events[${index}].at is invalid`);
      }
      for (const field of ["previous_outcome", "corrected_outcome"]) {
        if (
          event[field] !== undefined &&
          !["", "no_response", "replied", "interview", "offer", "rejected"].includes(
            event[field]
          )
        ) {
          errors.push(`outcome_events[${index}].${field} is invalid`);
        }
      }
    }
  }
  for (const field of schema?.timestamp_fields ?? []) {
    const value = record?.[field];
    if (value === "" || value === undefined || value === null) continue;
    if (typeof value !== "string" || !Number.isFinite(Date.parse(value))) {
      errors.push(`${field} must be a valid timestamp`);
    }
  }
  const canonicalUrl = normalizeCanonicalUrl(record?.canonical_url);
  const expectedIdentity = canonicalJobId(record ?? {});
  if (!canonicalUrl) errors.push("canonical_url is invalid");
  if (!String(record?.source_job_id || "").trim()) {
    errors.push("source_job_id is required");
  }
  if (!expectedIdentity || record?.canonical_job_id !== expectedIdentity) {
    errors.push("canonical_job_id does not match the canonical source identity");
  }
  const allowedActions =
    schema?.actions_by_status?.[record?.pipeline_status] ?? [];
  if (!allowedActions.includes(record?.user_action ?? "")) {
    errors.push("user_action is not supported for pipeline_status");
  }
  return errors;
}

function applyValidatedRecordUpdate(record, updates, schema) {
  const candidate = { ...record, ...updates };
  const errors = validateRecordContract(candidate, schema);
  if (errors.length > 0) {
    throw new Error(`Invalid record update: ${errors.join("; ")}`);
  }
  return candidate;
}

function validatePipelineSchema(schema) {
  const errors = [];
  if (schema?.schema_version !== 2) errors.push("schema_version must be 2");
  if (!Array.isArray(schema?.fields) || schema.fields.length === 0) errors.push("fields are required");
  if (!Array.isArray(schema?.pipeline_statuses) || schema.pipeline_statuses.length === 0) {
    errors.push("pipeline_statuses are required");
  }
  const duplicateFields = schema?.fields?.filter((field, index, all) => all.indexOf(field) !== index) ?? [];
  if (duplicateFields.length > 0) errors.push(`duplicate fields: ${[...new Set(duplicateFields)].join(", ")}`);
  const fields = new Set(schema?.fields ?? []);
  for (const collection of ["string_list_fields", "json_array_fields", "timestamp_fields"]) {
    if (!Array.isArray(schema?.[collection])) {
      errors.push(`${collection} must be an array`);
      continue;
    }
    for (const field of schema[collection]) {
      if (!fields.has(field)) errors.push(`${collection} references unknown field: ${field}`);
    }
  }
  for (const [field, rule] of Object.entries(schema?.field_rules ?? {})) {
    if (!fields.has(field)) errors.push(`field rule references unknown field: ${field}`);
    if (!["number", "integer", "enum", "string"].includes(rule?.type)) {
      errors.push(`field rule has unsupported type for ${field}`);
    }
    if (rule?.type === "enum" && (!Array.isArray(rule.values) || rule.values.length === 0)) {
      errors.push(`enum field rule requires values for ${field}`);
    }
    if (rule?.type === "string" && rule.pattern) {
      try {
        new RegExp(rule.pattern);
      } catch {
        errors.push(`string field rule has invalid pattern for ${field}`);
      }
    }
  }

  const statuses = new Set(schema?.pipeline_statuses ?? []);
  const businessResults = new Set(schema?.business_results ?? []);
  const operationalConditions = new Set(schema?.operational_conditions ?? []);
  if (businessResults.size !== 3 ||
      !["ready_to_apply", "review_needed", "skip"].every((status) => businessResults.has(status))) {
    errors.push("business_results must contain only ready_to_apply, review_needed, and skip");
  }
  if ([...businessResults].some((status) => operationalConditions.has(status))) {
    errors.push("business results and operational conditions must be disjoint");
  }
  if (
    [...businessResults, ...operationalConditions].some(
      (status) => !statuses.has(status)
    ) ||
    statuses.size !== businessResults.size + operationalConditions.size
  ) {
    errors.push("pipeline_statuses must be exactly the business results and operational conditions");
  }
  const actions = new Set(schema?.user_actions ?? []);
  if (
    actions.size !== 5 ||
    !["", "I Applied", "Skip", "Approve", "Deny"].every((action) =>
      actions.has(action)
    )
  ) {
    errors.push("user_actions must contain only the supported operator actions");
  }
  for (const [from, destinations] of Object.entries(schema?.transitions ?? {})) {
    if (!statuses.has(from)) errors.push(`transition source is not a status: ${from}`);
    for (const to of destinations) {
      if (!statuses.has(to)) errors.push(`transition destination is not a status: ${to}`);
    }
  }
  for (const status of statuses) {
    if (!(status in (schema?.transitions ?? {}))) errors.push(`missing transitions for status: ${status}`);
    const supportedActions = schema?.actions_by_status?.[status];
    if (!Array.isArray(supportedActions) || supportedActions.length === 0) {
      errors.push(`missing actions_by_status for status: ${status}`);
    } else if (supportedActions.some((action) => !actions.has(action))) {
      errors.push(`actions_by_status contains an unsupported action for status: ${status}`);
    }
  }
  return errors;
}

function validateUniqueIdentityAcrossStores(stores, schema, now = new Date().toISOString()) {
  const errors = [];
  const identities = new Map();
  for (const [store, rows] of Object.entries(stores ?? {})) {
    if (!Array.isArray(rows)) {
      errors.push(`${store} rows must be an array`);
      continue;
    }
    for (const [index, raw] of rows.entries()) {
      const record = normalizeLegacyRecord(raw, schema, now);
      const identity = String(record.canonical_job_id || "")
        .normalize("NFKC")
        .toLocaleLowerCase("en-US");
      if (!identity) {
        errors.push(`${store} row ${index + 2} has invalid identity`);
        continue;
      }
      const previous = identities.get(identity);
      if (previous) {
        errors.push(
          `duplicate canonical identity at ${previous.store} row ${previous.row} and ${store} row ${index + 2}`
        );
      } else {
        identities.set(identity, { store, row: index + 2 });
      }
    }
  }
  return errors;
}

function canTransition(schema, from, to) {
  return (schema.transitions?.[from] ?? []).includes(to);
}

function transitionRecord(record, to, schema, now = new Date().toISOString()) {
  const from = record.pipeline_status;
  if (!canTransition(schema, from, to)) {
    throw new Error(`Invalid pipeline transition: ${from} -> ${to}`);
  }
  const next = {
    ...record,
    pipeline_status: to,
    updated_at: now
  };
  return { ...next, state_guard: stateGuard(next) };
}

function isStaleClaim(record, nowMs, leaseMs) {
  if (!record.processing_token || !record.processing_started_at) return true;
  const startedAt = Date.parse(record.processing_started_at);
  return !Number.isFinite(startedAt) || nowMs - startedAt >= leaseMs;
}

function processingCommitGuard(token) {
  const value = String(token || "").trim();
  return value ? `commit:${value}` : "";
}

function claimRecord(record, { stage, token, now, leaseMs }) {
  const nowMs = Date.parse(now);
  if (!stage || !token || !Number.isFinite(nowMs) || !Number.isFinite(leaseMs) || leaseMs < 1) {
    throw new Error("stage, token, valid now, and positive leaseMs are required");
  }
  if (record.processing_token && !isStaleClaim(record, nowMs, leaseMs)) {
    return { claimed: false, record };
  }
  return {
    claimed: true,
    record: {
      ...record,
      processing_stage: stage,
      processing_token: token,
      processing_commit_guard: processingCommitGuard(token),
      processing_started_at: now,
      updated_at: now
    }
  };
}

function releaseClaim(record, token, now = new Date().toISOString()) {
  if (record.processing_token && record.processing_token !== token) {
    throw new Error("processing token mismatch");
  }
  const next = {
    ...record,
    processing_stage: "",
    processing_token: "",
    processing_started_at: "",
    updated_at: now
  };
  return { ...next, state_guard: stateGuard(next) };
}

function createProcessingClaim(record, executionId, now, leaseMs) {
  const token = `${executionId}:${record.canonical_job_id}:${record.work_stage}`;
  return {
    canonical_job_id: record.canonical_job_id,
    processing_stage: record.work_stage,
    processing_token: token,
    created_at: now,
    expires_at: new Date(Date.parse(now) + leaseMs).toISOString()
  };
}

function chooseWinningClaims(proposedRecords, allClaims, now = new Date().toISOString()) {
  const claimKey = (record) =>
    `${String(record?.canonical_job_id || "")
      .trim()
      .normalize("NFKC")
      .toLocaleLowerCase("en-US")}:${String(
      record?.processing_stage || record?.work_stage || ""
    ).trim()}`;
  const nowMs = Date.parse(now);
  const expectedLeaseMsByKey = new Map();
  for (const record of proposedRecords) {
    const claimCreatedAt = Date.parse(
      record?.claim_created_at ?? record?.created_at
    );
    const claimExpiresAt = Date.parse(
      record?.claim_expires_at ?? record?.expires_at
    );
    const leaseMs = claimExpiresAt - claimCreatedAt;
    if (Number.isFinite(leaseMs) && leaseMs > 0) {
      expectedLeaseMsByKey.set(claimKey(record), leaseMs);
    }
  }
  const rowNumberCounts = new Map();
  for (const claim of allClaims) {
    const rowNumber = Number(claim?.row_number);
    if (!Number.isInteger(rowNumber) || rowNumber < 2) continue;
    rowNumberCounts.set(
      rowNumber,
      (rowNumberCounts.get(rowNumber) || 0) + 1
    );
  }
  const validClaims = allClaims.filter((claim) => {
    const createdAt = Date.parse(claim.created_at);
    const expiresAt = Date.parse(claim.expires_at);
    const rowNumber = Number(claim.row_number);
    const expectedLeaseMs = expectedLeaseMsByKey.get(claimKey(claim));
    return (
      claim.canonical_job_id &&
      claim.processing_stage &&
      claim.processing_token &&
      Number.isFinite(createdAt) &&
      Number.isFinite(expiresAt) &&
      createdAt <= nowMs &&
      expiresAt > createdAt &&
      expiresAt > nowMs &&
      (!Number.isFinite(expectedLeaseMs) ||
        expiresAt - createdAt <= expectedLeaseMs) &&
      Number.isInteger(rowNumber) &&
      rowNumber >= 2 &&
      rowNumberCounts.get(rowNumber) === 1
    );
  });
  const winners = new Map();
  for (const claim of validClaims) {
    const key = claimKey(claim);
    const current = winners.get(key);
    const claimRow = Number(claim.row_number);
    if (!current || claimRow < Number(current.row_number)) {
      winners.set(key, claim);
    }
  }
  const emitted = new Set();
  return proposedRecords.filter((record) => {
    const key = claimKey(record);
    if (
      emitted.has(key) ||
      winners.get(key)?.processing_token !== record.processing_token
    ) {
      return false;
    }
    emitted.add(key);
    return true;
  });
}


const WINDOW_MS = 24 * 60 * 60 * 1000;

function decodeHtml(value = "") {
  const named = {
    amp: "&",
    apos: "'",
    gt: ">",
    lt: "<",
    nbsp: " ",
    quot: "\"",
    "#039": "'",
    "#8211": "–",
    "#8212": "—",
    "#8230": "…"
  };
  return String(value)
    .replace(/&#x([0-9a-f]+);/gi, (_, hex) =>
      String.fromCodePoint(Number.parseInt(hex, 16))
    )
    .replace(/&#(\d+);/g, (_, decimal) =>
      String.fromCodePoint(Number.parseInt(decimal, 10))
    )
    .replace(
      /&([a-z]+|#\d+);/gi,
      (entity, name) => named[name.toLowerCase()] ?? entity
    );
}

function textFromHtml(value = "") {
  return decodeHtml(
    String(value)
      .replace(/<br\s*\/?>/gi, "\n")
      .replace(/<[^>]+>/g, " ")
  )
    .replace(/\s+/g, " ")
    .trim();
}

function parsePostedAt(value) {
  const input = String(value || "").trim();
  if (!input) return "";
  const normalized = input.includes("T")
    ? input
    : `${input.replace(" ", "T")}+08:00`;
  const timestamp = Date.parse(normalized);
  return Number.isFinite(timestamp) ? new Date(timestamp).toISOString() : "";
}

function createDiscoveryWindow(now = new Date().toISOString()) {
  const windowEndMs = Date.parse(now);
  if (!Number.isFinite(windowEndMs)) {
    throw new Error("Discovery window requires a valid execution timestamp");
  }
  return Object.freeze({
    window_start: new Date(windowEndMs - WINDOW_MS).toISOString(),
    window_end: new Date(windowEndMs).toISOString(),
    window_hours: 24
  });
}

function validateSearchPlan(plan) {
  const errors = [];
  if (plan?.schema_version !== 2) {
    errors.push("search plan schema_version must be 2");
  }
  if (!/^\d{4}-\d{2}-\d{2}\/v\d+$/.test(plan?.plan_version || "")) {
    errors.push("search plan plan_version must use YYYY-MM-DD/vN");
  }
  if (plan?.source !== "onlinejobs.ph") {
    errors.push("search plan source must be onlinejobs.ph");
  }
  if (plan?.window_hours !== 24) {
    errors.push("window_hours must be exactly 24");
  }
  if (plan?.pagination_mode !== "adaptive_source_exhaustion") {
    errors.push("pagination_mode must be adaptive_source_exhaustion");
  }
  for (const field of [
    "schedule_minutes",
    "execution_timeout_seconds",
    "page_size",
    "max_pages_per_keyword",
    "request_interval_ms",
    "request_timeout_ms",
    "claim_lease_ms"
  ]) {
    if (!Number.isInteger(plan?.[field]) || plan[field] < 1) {
      errors.push(`${field} must be a positive integer`);
    }
  }
  if (
    Number.isInteger(plan?.execution_timeout_seconds) &&
    Number.isInteger(plan?.schedule_minutes) &&
    plan.execution_timeout_seconds >= plan.schedule_minutes * 60
  ) {
    errors.push("execution timeout must be shorter than the discovery schedule");
  }
  if (
    Number.isInteger(plan?.request_timeout_ms) &&
    Number.isInteger(plan?.execution_timeout_seconds) &&
    plan.request_timeout_ms >= plan.execution_timeout_seconds * 1000
  ) {
    errors.push("request timeout must be shorter than execution timeout");
  }
  errors.push(...validateMinuteIntervalSchedule(plan, "discovery"));

  if (!Array.isArray(plan?.keywords) || plan.keywords.length === 0) {
    errors.push("at least one keyword is required");
    return errors;
  }
  const ids = new Set();
  const values = new Set();
  for (const entry of plan.keywords) {
    const id = String(entry?.id || "").trim();
    const keyword = String(entry?.keyword || "").trim();
    if (!id || !keyword || typeof entry?.enabled !== "boolean") {
      errors.push("every keyword requires id, keyword, and enabled");
      continue;
    }
    const normalized = keyword.normalize("NFKC").toLocaleLowerCase("en-US");
    if (ids.has(id)) errors.push(`duplicate keyword id: ${id}`);
    if (values.has(normalized)) errors.push(`duplicate keyword: ${keyword}`);
    ids.add(id);
    values.add(normalized);
    if ("evidence_refs" in entry || "role_family" in entry) {
      errors.push(`keyword ${id} must not contain resume or adjacent-role metadata`);
    }
  }
  if (!plan.keywords.some((entry) => entry.enabled)) {
    errors.push("at least one keyword must be enabled");
  }
  return errors;
}

function searchRequest(keyword, pageNumber, plan, window) {
  const offset = (pageNumber - 1) * plan.page_size;
  const path =
    pageNumber === 1
      ? "/jobseekers/jobsearch"
      : `/jobseekers/jobsearch/${offset}`;
  return {
    keyword_id: keyword.id,
    keyword: keyword.keyword,
    page_number: pageNumber,
    request_url:
      `https://www.onlinejobs.ph${path}?jobkeyword=` +
      encodeURIComponent(keyword.keyword),
    window_start: window.window_start,
    window_end: window.window_end
  };
}

function buildSearchRequests(
  plan,
  window = createDiscoveryWindow()
) {
  return plan.keywords
    .filter((entry) => entry.enabled)
    .map((keyword) => searchRequest(keyword, 1, plan, window));
}

function sourceResultCardCount(page) {
  if (Number.isInteger(page?.result_card_count) && page.result_card_count >= 0) {
    return page.result_card_count;
  }
  return ["jobs", "excluded", "malformed"].reduce(
    (total, field) =>
      total + (Array.isArray(page?.[field]) ? page[field].length : 0),
    0
  );
}

function sourcePageExhausted(page) {
  return Boolean(page?.ok && !page.has_next);
}

function buildNextSearchRequest(page, plan) {
  if (
    !page?.ok ||
    sourcePageExhausted(page) ||
    !Number.isInteger(page.page_number) ||
    page.page_number < 1 ||
    page.page_number >= plan.max_pages_per_keyword
  ) {
    return null;
  }
  return searchRequest(
    { id: page.keyword_id, keyword: page.keyword },
    page.page_number + 1,
    plan,
    {
      window_start: page.window_start,
      window_end: page.window_end
    }
  );
}

function advanceSearchPagination(state, page, plan) {
  if (
    state?.window_start &&
    (state.window_start !== page?.window_start ||
      state.window_end !== page?.window_end)
  ) {
    throw new Error("Discovery page changed the immutable execution window");
  }
  const nextRequest = buildNextSearchRequest(page, plan);
  return {
    ...state,
    ...(nextRequest || {}),
    page_results: [
      ...(Array.isArray(state?.page_results) ? state.page_results : []),
      page
    ],
    fetch_next_page: Boolean(nextRequest)
  };
}

function parseSearchResults(html, request) {
  const jobs = [];
  const excluded = [];
  const malformed = [];
  const windowStartMs = Date.parse(request?.window_start || "");
  const windowEndMs = Date.parse(request?.window_end || "");
  if (
    !Number.isFinite(windowStartMs) ||
    !Number.isFinite(windowEndMs) ||
    windowEndMs - windowStartMs !== WINDOW_MS
  ) {
    throw new Error("Search parsing requires one valid fixed 24-hour window");
  }

  const pageText = String(html || "");
  const cardRegex =
    /<a\s+href=["'](\/jobseekers\/job\/[^"']+)["'][^>]*>\s*<div[^>]*class=["'][^"']*jobpost-cat-box[^"']*["'][^>]*>([\s\S]*?)<\/div>\s*<\/a>/gi;
  let resultCardCount = 0;
  let match;
  while ((match = cardRegex.exec(pageText)) !== null) {
    resultCardCount += 1;
    const urlPath = match[1];
    const cardHtml = match[2];
    const titleMatch = cardHtml.match(/<h4[^>]*>([\s\S]*?)<\/h4>/i);
    const dateMatch =
      cardHtml.match(/data-temp=["']([^"']+)["']/i) ||
      cardHtml.match(/<em>\s*Posted on\s+([^<]+)<\/em>/i);
    if (!titleMatch) {
      malformed.push({ url_path: urlPath, reason: "missing_title" });
      continue;
    }
    if (!dateMatch) {
      malformed.push({ url_path: urlPath, reason: "missing_posted_at" });
      continue;
    }

    const title = textFromHtml(
      titleMatch[1].replace(
        /<span[^>]*class=["'][^"']*badge[^"']*["'][^>]*>[\s\S]*?<\/span>/gi,
        ""
      )
    );
    const postedAt = parsePostedAt(dateMatch[1]);
    if (!title) {
      malformed.push({ url_path: urlPath, reason: "empty_title" });
      continue;
    }
    if (!postedAt) {
      malformed.push({ url_path: urlPath, reason: "invalid_posted_at" });
      continue;
    }
    const postedAtMs = Date.parse(postedAt);
    if (postedAtMs < windowStartMs) {
      excluded.push({
        url_path: urlPath,
        posted_at: postedAt,
        reason: "outside_window_old"
      });
      continue;
    }
    if (postedAtMs > windowEndMs) {
      excluded.push({
        url_path: urlPath,
        posted_at: postedAt,
        reason: "future_dated"
      });
      continue;
    }

    const salaryMatch = cardHtml.match(
      /<dd\s+class=["']col["'][^>]*>([\s\S]*?)<\/dd>/i
    );
    const descriptionMatch = cardHtml.match(
      /<div[^>]*class=["'][^"']*\bdesc\b[^"']*["'][^>]*>([\s\S]*?)<\/div>/i
    );
    const canonicalUrl = normalizeCanonicalUrl(urlPath);
    const job = {
      source: "onlinejobs.ph",
      source_job_id: extractOnlineJobsId(canonicalUrl),
      canonical_url: canonicalUrl,
      job_title: title,
      company: "",
      salary_text: textFromHtml(salaryMatch?.[1] ?? ""),
      search_summary: textFromHtml(descriptionMatch?.[1] ?? ""),
      posted_at: postedAt,
      matched_keywords: [request.keyword],
      source_availability: "active"
    };
    job.canonical_job_id = canonicalJobId(job);
    if (!job.canonical_job_id) {
      malformed.push({ url_path: urlPath, reason: "invalid_identity" });
      continue;
    }
    jobs.push(job);
  }

  const hasNext = /<a[^>]+rel=["']next["'][^>]*>/i.test(pageText);
  const pageNumbers = [
    ...pageText.matchAll(/data-ci-pagination-page=["'](\d+)["']/gi)
  ].map((entry) => Number(entry[1]));
  const reportedLastPage =
    pageNumbers.length > 0 ? Math.max(...pageNumbers) : request.page_number;
  const explicitEmpty =
    /\bno\s+(?:job\s+posts?|jobs?)\s+(?:matched|found|available)\b/i.test(
      textFromHtml(pageText)
    );
  const hasSearchPageEvidence = resultCardCount > 0 || explicitEmpty;
  return {
    ...request,
    ok: hasSearchPageEvidence,
    jobs,
    excluded,
    malformed,
    result_card_count: resultCardCount,
    has_next: hasNext,
    reported_last_page: reportedLastPage,
    ...(hasSearchPageEvidence
      ? {}
      : {
          error_category: "unexpected_search_page",
          error_summary:
            "Search response lacked recognizable result-page evidence."
        })
  };
}

function effectivePagesForKeyword(pages) {
  const sorted = [...pages].sort((left, right) => left.page_number - right.page_number);
  const effective = [];
  for (const page of sorted) {
    effective.push(page);
    if (sourcePageExhausted(page)) break;
  }
  return effective;
}

function summarizeCoverage(pageResults, plan) {
  const keywords = [];
  for (const keyword of plan.keywords.filter((entry) => entry.enabled)) {
    const pages = effectivePagesForKeyword(
      pageResults.filter((result) => result.keyword_id === keyword.id)
    );
    const successes = pages.filter((page) => page.ok);
    const failures = pages.filter((page) => !page.ok);
    const lastSuccess = successes.at(-1);
    let status = "failed";
    let stopReason = failures.length > 0 ? "request_failure" : "no_page_result";
    if (successes.length > 0 && failures.length > 0) {
      status = "partial";
    } else if (
      successes.length > 0 &&
      sourceResultCardCount(successes[0]) === 0 &&
      sourcePageExhausted(successes[0])
    ) {
      status = "empty";
      stopReason = "no_results";
    } else if (lastSuccess && sourcePageExhausted(lastSuccess)) {
      status = "complete";
      stopReason = "source_exhausted";
    } else if (
      lastSuccess?.page_number >= plan.max_pages_per_keyword
    ) {
      status = "partial";
      stopReason = "page_limit";
    } else if (successes.length > 0) {
      status = "partial";
      stopReason = "incomplete_pages";
    }
    keywords.push({
      keyword_id: keyword.id,
      keyword: keyword.keyword,
      status,
      stop_reason: stopReason,
      pages_succeeded: successes.length,
      pages_failed: failures.length,
      result_cards_seen: successes.reduce(
        (total, page) => total + sourceResultCardCount(page),
        0
      ),
      jobs_found: successes.reduce(
        (total, page) => total + page.jobs.length,
        0
      ),
      malformed_count: successes.reduce(
        (total, page) => total + page.malformed.length,
        0
      ),
      excluded_count: successes.reduce(
        (total, page) => total + page.excluded.length,
        0
      )
    });
  }
  return {
    status: keywords.some(
      (entry) => entry.status === "failed" || entry.status === "partial"
    )
      ? "partial"
      : keywords.every((entry) => entry.status === "empty")
        ? "empty"
        : "complete",
    pages_requested: keywords.reduce(
      (total, entry) => total + entry.pages_succeeded + entry.pages_failed,
      0
    ),
    maximum_page_requests:
      plan.keywords.filter((entry) => entry.enabled).length *
      plan.max_pages_per_keyword,
    keywords
  };
}

function unionValues(...collections) {
  return [
    ...new Set(
      collections
        .flat()
        .filter(Boolean)
        .map((value) => String(value).trim())
    )
  ];
}

function identityKey(value) {
  return String(value || "")
    .trim()
    .normalize("NFKC")
    .toLocaleLowerCase("en-US");
}

function reconcileDiscovery(
  pageResults,
  reviewRows,
  appliedRows,
  archiveRows,
  schema,
  now = new Date().toISOString()
) {
  const identityErrors = validateUniqueIdentityAcrossStores(
    {
      "Review Queue": reviewRows,
      "Applied Jobs": appliedRows,
      Archive: archiveRows
    },
    schema,
    now
  );
  if (identityErrors.length > 0) {
    throw new Error(`Discovery store identity check failed: ${identityErrors.join("; ")}`);
  }

  const existing = new Map();
  for (const [location, rows] of [
    ["review", reviewRows],
    ["applied", appliedRows],
    ["archive", archiveRows]
  ]) {
    for (const raw of rows) {
      const normalized = normalizeLegacyRecord(raw, schema, now);
      const entry = { location, raw, normalized };
      existing.set(identityKey(normalized.canonical_job_id), entry);
      existing.set(`url:${identityKey(normalized.canonical_url)}`, entry);
    }
  }

  const discovered = new Map();
  let malformedCount = 0;
  const exclusionCounts = {};
  for (const page of pageResults.filter((result) => result.ok)) {
    malformedCount += page.malformed.length;
    for (const excluded of page.excluded) {
      exclusionCounts[excluded.reason] =
        (exclusionCounts[excluded.reason] || 0) + 1;
    }
    for (const job of page.jobs) {
      const key = identityKey(job.canonical_job_id);
      const current = discovered.get(key);
      if (current) {
        current.matched_keywords = unionValues(
          current.matched_keywords,
          job.matched_keywords
        );
      } else {
        discovered.set(key, {
          ...job,
          matched_keywords: [...job.matched_keywords]
        });
      }
    }
  }

  const newJobs = [];
  const reviewUpdates = [];
  let terminalSuppressed = 0;
  for (const job of discovered.values()) {
    const match =
      existing.get(identityKey(job.canonical_job_id)) ||
      existing.get(`url:${identityKey(job.canonical_url)}`);
    if (match?.location === "review") {
      const updated = {
        ...match.normalized,
        row_number: match.raw.row_number,
        source_job_id: job.source_job_id,
        canonical_job_id: job.canonical_job_id,
        canonical_url: job.canonical_url,
        matched_keywords: unionValues(
          match.normalized.matched_keywords,
          job.matched_keywords
        ),
        last_seen_at: now,
        updated_at: now
      };
      reviewUpdates.push(updated);
      continue;
    }
    if (match) {
      terminalSuppressed += 1;
      continue;
    }
    const record = normalizeLegacyRecord(
      {
        ...job,
        pipeline_status: "new",
        user_action: "",
        record_version: 1,
        discovered_at: now,
        last_seen_at: now,
        created_at: now,
        updated_at: now,
        attempt_count: 0,
        alert_attempt_count: 0,
        outcome: ""
      },
      schema,
      now
    );
    record.state_guard = stateGuard(record);
    newJobs.push(record);
  }

  return {
    new_jobs: newJobs,
    review_updates: reviewUpdates,
    discovered_unique: discovered.size,
    terminal_suppressed: terminalSuppressed,
    malformed_count: malformedCount,
    exclusion_counts: exclusionCounts
  };
}

const SEARCH_PLAN = {"schema_version":2,"plan_version":"2026-07-31/v1","source":"onlinejobs.ph","schedule_minutes":240,"schedule_offset_minutes":8,"execution_timeout_seconds":900,"window_hours":24,"page_size":30,"max_pages_per_keyword":3,"pagination_mode":"adaptive_source_exhaustion","request_interval_ms":2000,"request_timeout_ms":15000,"claim_lease_ms":1200000,"retry":{"max_attempts":3,"backoff_ms":5000},"keywords":[{"id":"full-stack","keyword":"full stack developer","enabled":true},{"id":"web","keyword":"web developer","enabled":true},{"id":"react","keyword":"react developer","enabled":true},{"id":"nextjs","keyword":"nextjs developer","enabled":true},{"id":"nodejs","keyword":"nodejs developer","enabled":true},{"id":"backend","keyword":"backend developer","enabled":true},{"id":"flutter","keyword":"flutter developer","enabled":true},{"id":"n8n","keyword":"n8n developer","enabled":true},{"id":"automation","keyword":"automation developer","enabled":true},{"id":"support","keyword":"application support engineer","enabled":true}]};
const errors = validateSearchPlan(SEARCH_PLAN);
if (errors.length) throw new Error('Invalid search plan: ' + errors.join('; '));
const window = createDiscoveryWindow(new Date().toISOString());
return buildSearchRequests(SEARCH_PLAN, window).map((request) => ({ json: request }));

const DAY_MINUTES = 24 * 60;
const DAY_HOURS = 24;

function validateMinuteIntervalSchedule(
  config,
  label = "interval schedule"
) {
  const errors = [];
  const intervalMinutes = config?.schedule_minutes;
  const offsetMinutes = config?.schedule_offset_minutes;
  if (
    !Number.isInteger(intervalMinutes) ||
    intervalMinutes < 1 ||
    intervalMinutes > DAY_MINUTES ||
    DAY_MINUTES % intervalMinutes !== 0
  ) {
    errors.push(
      `${label} schedule_minutes must be a positive divisor of ${DAY_MINUTES}`
    );
  }
  if (
    !Number.isInteger(offsetMinutes) ||
    offsetMinutes < 0 ||
    (Number.isInteger(intervalMinutes) && offsetMinutes >= intervalMinutes)
  ) {
    errors.push(
      `${label} schedule_offset_minutes must be from 0 through schedule_minutes - 1`
    );
  }
  return errors;
}

function minuteIntervalExecutionMinutes(
  config,
  label = "interval schedule"
) {
  const errors = validateMinuteIntervalSchedule(config, label);
  if (errors.length > 0) {
    throw new Error(`Invalid ${label}:\n- ${errors.join("\n- ")}`);
  }
  const minutes = [];
  for (
    let minute = config.schedule_offset_minutes;
    minute < DAY_MINUTES;
    minute += config.schedule_minutes
  ) {
    minutes.push(minute);
  }
  return minutes;
}

function minuteIntervalScheduleRules(
  config,
  label = "interval schedule"
) {
  const executionMinutes = minuteIntervalExecutionMinutes(config, label);
  const hoursByMinute = new Map();
  for (const executionMinute of executionMinutes) {
    const minute = executionMinute % 60;
    const hour = Math.floor(executionMinute / 60);
    if (!hoursByMinute.has(minute)) hoursByMinute.set(minute, []);
    hoursByMinute.get(minute).push(hour);
  }
  const minutesByHours = new Map();
  for (const [minute, hours] of hoursByMinute) {
    const key = hours.join(",");
    if (!minutesByHours.has(key)) {
      minutesByHours.set(key, { hours, minutes: [] });
    }
    minutesByHours.get(key).minutes.push(minute);
  }
  return [...minutesByHours.values()]
    .map(({ hours, minutes }) => ({
      firstExecutionMinute: Math.min(
        ...executionMinutes.filter(
          (executionMinute) =>
            minutes.includes(executionMinute % 60) &&
            hours.includes(Math.floor(executionMinute / 60))
        )
      ),
      rule: {
        field: "cronExpression",
        expression: `0 ${minutes
          .sort((left, right) => left - right)
          .join(",")} ${
          hours.length === DAY_HOURS ? "*" : hours.join(",")
        } * * *`
      }
    }))
    .sort(
      (left, right) =>
        left.firstExecutionMinute - right.firstExecutionMinute
    )
    .map(({ rule }) => rule);
}


function parseHttpUrl(value, { baseOrigin = "" } = {}) {
  let input = String(value ?? "").trim();
  if (!input) return null;

  if (input.startsWith("/")) {
    const base = parseHttpUrl(baseOrigin);
    if (!base) return null;
    input = `${base.protocol}//${base.hostname}${base.port ? `:${base.port}` : ""}${input}`;
  }

  if (/[\u0000-\u0020\u007f\\]/.test(input)) return null;
  const match = input.match(
    /^(https?):\/\/([^/?#]+)(\/[^?#]*)?(\?[^#]*)?(#.*)?$/i
  );
  if (!match) return null;

  const protocol = `${match[1].toLowerCase()}:`;
  const authority = match[2];
  if (!authority || authority.includes("@") || authority.includes("[")) return null;

  const colonIndex = authority.lastIndexOf(":");
  let hostname = authority;
  let port = "";
  if (colonIndex >= 0) {
    if (authority.indexOf(":") !== colonIndex) return null;
    hostname = authority.slice(0, colonIndex);
    port = authority.slice(colonIndex + 1);
    if (!/^\d{1,5}$/.test(port)) return null;
    const portNumber = Number(port);
    if (portNumber < 1 || portNumber > 65535) return null;
  }

  hostname = hostname.toLowerCase();
  if (
    hostname.length > 253 ||
    hostname.split(".").some(
      (label) =>
        !label ||
        label.length > 63 ||
        !/^[a-z0-9](?:[a-z0-9-]*[a-z0-9])?$/i.test(label)
    )
  ) {
    return null;
  }

  const pathname = match[3] || "/";
  const search = match[4] || "";
  const hash = match[5] || "";
  return {
    protocol,
    hostname,
    port,
    pathname,
    search,
    hash,
    username: "",
    password: "",
    href: `${protocol}//${hostname}${port ? `:${port}` : ""}${pathname}${search}${hash}`
  };
}

function normalizeCanonicalUrl(value) {
  const parsed = parseHttpUrl(value, {
    baseOrigin: "https://www.onlinejobs.ph"
  });
  if (!parsed) return "";
  if (parsed.port && parsed.port !== "443") return "";
  const hostname =
    parsed.hostname === "www.onlinejobs.ph"
      ? "onlinejobs.ph"
      : parsed.hostname;
  if (hostname !== "onlinejobs.ph") return "";
  const pathname = parsed.pathname.replace(/\/+/g, "/").replace(/\/$/, "");
  if (!/^\/jobseekers\/job\/[^/]+$/i.test(pathname)) return "";
  return `https://${hostname}${pathname}`;
}

function extractOnlineJobsId(url) {
  const canonicalUrl = normalizeCanonicalUrl(url);
  if (!canonicalUrl) return "";
  const match = canonicalUrl.match(/\/jobseekers\/job\/[^/]*?(\d+)$/i);
  return match?.[1] ?? "";
}

function canonicalJobId(record) {
  const source = String(record.source || "onlinejobs.ph").trim().toLowerCase();
  const sourceJobId = String(record.source_job_id || extractOnlineJobsId(record.canonical_url || record.job_url) || "").trim();
  if (sourceJobId) return `${source}:${sourceJobId}`;
  const canonicalUrl = normalizeCanonicalUrl(record.canonical_url || record.job_url);
  if (!canonicalUrl) return "";
  let hash = 2166136261;
  for (let index = 0; index < canonicalUrl.length; index += 1) {
    hash ^= canonicalUrl.charCodeAt(index);
    hash = Math.imul(hash, 16777619);
  }
  const digest = (hash >>> 0).toString(16).padStart(8, "0");
  return `${source}:url:${digest}`;
}

function stateGuard(record) {
  const canonicalId = String(record.canonical_job_id || canonicalJobId(record) || "");
  if (!canonicalId) return "";
  const state = [
    canonicalId,
    String(record.pipeline_status || ""),
    String(record.user_action || ""),
    String(record.record_version || ""),
    String(record.processing_stage || ""),
    String(record.processing_token || ""),
    String(record.generated_at || ""),
    String(record.alert_status || ""),
    String(record.outcome || ""),
    String(record.applied_at || ""),
    String(record.archived_at || ""),
    String(record.archive_reason || "")
  ].join("\u001f");
  let hash = 2166136261;
  for (let index = 0; index < state.length; index += 1) {
    hash ^= state.charCodeAt(index);
    hash = Math.imul(hash, 16777619);
  }
  return `${canonicalId}|${(hash >>> 0).toString(16).padStart(8, "0")}`;
}

function rankingPriorityValue(record) {
  if (
    typeof record?.opportunity_score === "number" &&
    Number.isFinite(record.opportunity_score)
  ) {
    return {
      value: record.opportunity_score,
      source: "opportunity_score"
    };
  }
  if (typeof record?.match_score === "number" && Number.isFinite(record.match_score)) {
    return {
      value: record.match_score,
      source: "legacy_match_score"
    };
  }
  return { value: 0, source: "missing" };
}

function compareRankingPriority(left, right) {
  const scoreOrder =
    rankingPriorityValue(right).value - rankingPriorityValue(left).value;
  if (scoreOrder !== 0) return scoreOrder;
  const confidenceOrder =
    ({ high: 3, medium: 2, low: 1 }[right.ranking_confidence] ?? 0) -
    ({ high: 3, medium: 2, low: 1 }[left.ranking_confidence] ?? 0);
  if (confidenceOrder !== 0) return confidenceOrder;
  const timestamp = (value) => {
    const parsed = Date.parse(value || "");
    return Number.isFinite(parsed) ? parsed : Number.NEGATIVE_INFINITY;
  };
  const rightPosted = timestamp(right.posted_at);
  const leftPosted = timestamp(left.posted_at);
  if (rightPosted !== leftPosted) return rightPosted - leftPosted;
  const rightCreated = timestamp(right.created_at);
  const leftCreated = timestamp(left.created_at);
  if (rightCreated !== leftCreated) return rightCreated - leftCreated;
  return String(left.canonical_job_id || "").localeCompare(
    String(right.canonical_job_id || "")
  );
}

function parseList(value) {
  if (Array.isArray(value)) return value.filter(Boolean);
  if (!value) return [];
  try {
    const parsed = JSON.parse(value);
    if (Array.isArray(parsed)) return parsed.filter(Boolean);
  } catch {
    // Legacy sheets may use comma-separated values.
  }
  return String(value)
    .split(",")
    .map((part) => part.trim())
    .filter(Boolean);
}

function parseJsonArray(value) {
  if (Array.isArray(value)) return value;
  if (!value) return [];
  try {
    const parsed = JSON.parse(value);
    return Array.isArray(parsed) ? parsed : value;
  } catch {
    return value;
  }
}

function normalizeRuleValue(value, rule) {
  if (!rule || value === "" || value === undefined || value === null) return value ?? "";
  if (rule.type === "number" || rule.type === "integer") {
    const numeric = Number(value);
    return Number.isFinite(numeric) ? numeric : value;
  }
  if (rule.type === "string") return String(value).trim();
  return value;
}

function mergeOutcomeEvents(...collections) {
  const events = new Map();
  for (const collection of collections) {
    if (!Array.isArray(collection)) continue;
    for (const event of collection) {
      if (!event || typeof event !== "object" || Array.isArray(event)) continue;
      const id = String(event.id || "").trim();
      if (!id || events.has(id)) continue;
      events.set(id, { ...event, id });
    }
  }
  const timestamp = (value) => {
    const parsed = Date.parse(value || "");
    return Number.isFinite(parsed) ? parsed : Number.POSITIVE_INFINITY;
  };
  return [...events.values()].sort(
    (left, right) =>
      timestamp(left.at) - timestamp(right.at) ||
      String(left.id).localeCompare(String(right.id))
  );
}

function normalizeLegacyRecord(input, schema, now = new Date().toISOString()) {
  const record = { ...input };
  for (const [legacy, canonical] of Object.entries(schema.legacy_header_mapping ?? {})) {
    if (record[canonical] === undefined && record[legacy] !== undefined) {
      record[canonical] = record[legacy];
    }
  }

  const legacyStatus = String(record.pipeline_status || "").trim().toLowerCase();
  record.pipeline_status =
    schema.legacy_status_mapping?.[legacyStatus] ||
    (schema.pipeline_statuses.includes(legacyStatus) ? legacyStatus : "new");
  record.source = String(record.source || "onlinejobs.ph").trim().toLowerCase();
  record.canonical_url = normalizeCanonicalUrl(record.canonical_url || record.job_url);
  record.source_job_id = String(record.source_job_id || extractOnlineJobsId(record.canonical_url) || "");
  record.canonical_job_id = String(record.canonical_job_id || canonicalJobId(record));
  for (const field of schema.string_list_fields ?? ["matched_keywords"]) {
    record[field] = parseList(record[field]);
  }
  for (const field of schema.json_array_fields ?? []) {
    record[field] = parseJsonArray(record[field]);
  }
  for (const [field, rule] of Object.entries(schema.field_rules ?? {})) {
    record[field] = normalizeRuleValue(record[field], rule);
  }
  record.attempt_count = Number.isFinite(Number(record.attempt_count))
    ? Number(record.attempt_count)
    : 0;
  record.record_version = Number.isInteger(Number(record.record_version)) && Number(record.record_version) > 0
    ? Number(record.record_version)
    : 1;
  record.alert_attempt_count = Number.isFinite(Number(record.alert_attempt_count))
    ? Number(record.alert_attempt_count)
    : 0;
  record.created_at = record.created_at || now;
  record.updated_at = record.updated_at || now;
  record.source_availability = record.source_availability || "active";
  record.profile_version =
    record.profile_version ||
    (schema.schema_version === 1 ? "legacy/unknown" : "");
  record.message_profile_version =
    record.message_profile_version ||
    (schema.schema_version === 1 && record.generated_message
      ? "legacy/unknown"
      : "");
  record.outcome = record.outcome || "";
  record.user_action = record.user_action || "";
  record.state_guard = record.state_guard || stateGuard(record);
  return record;
}

function validateRecordContract(record, schema) {
  const errors = [];
  const fields = new Set(schema?.fields ?? []);
  for (const [field, rule] of Object.entries(schema?.field_rules ?? {})) {
    if (!fields.has(field)) {
      errors.push(`field rule references unknown field: ${field}`);
      continue;
    }
    const value = record?.[field];
    const missing = value === "" || value === undefined || value === null;
    if (missing) {
      if (rule.nullable === false) errors.push(`${field} is required`);
      continue;
    }
    if (rule.type === "enum") {
      if (!rule.values?.includes(value)) errors.push(`${field} has unsupported value: ${value}`);
      continue;
    }
    if (rule.type === "string") {
      if (typeof value !== "string") {
        errors.push(`${field} must be a string`);
        continue;
      }
      if (
        rule.maximum_length !== undefined &&
        value.length > rule.maximum_length
      ) {
        errors.push(`${field} exceeds its maximum length`);
      }
      if (rule.pattern && !new RegExp(rule.pattern).test(value)) {
        errors.push(`${field} has an unsupported format`);
      }
      continue;
    }
    const numeric = typeof value === "number" ? value : Number.NaN;
    if (!Number.isFinite(numeric)) {
      errors.push(`${field} must be a ${rule.type}`);
      continue;
    }
    if (rule.type === "integer" && !Number.isInteger(numeric)) {
      errors.push(`${field} must be an integer`);
    }
    if (rule.minimum !== undefined && numeric < rule.minimum) {
      errors.push(`${field} must be at least ${rule.minimum}`);
    }
    if (rule.maximum !== undefined && numeric > rule.maximum) {
      errors.push(`${field} must be at most ${rule.maximum}`);
    }
  }
  for (const field of schema?.string_list_fields ?? []) {
    const value = record?.[field];
    if (value !== undefined && !Array.isArray(value)) errors.push(`${field} must be an array`);
  }
  for (const field of schema?.json_array_fields ?? []) {
    const value = record?.[field];
    if (value !== undefined && !Array.isArray(value)) errors.push(`${field} must be a JSON array`);
  }
  if (Array.isArray(record?.outcome_events)) {
    const seen = new Set();
    const allowedTypes = new Set([
      "no_response",
      "replied",
      "interview",
      "offer",
      "rejected",
      "correction"
    ]);
    for (const [index, event] of record.outcome_events.entries()) {
      if (!event || typeof event !== "object" || Array.isArray(event)) {
        errors.push(`outcome_events[${index}] must be an object`);
        continue;
      }
      const id = String(event.id || "");
      if (!id || id.length > 256) {
        errors.push(`outcome_events[${index}].id is invalid`);
      } else if (seen.has(id)) {
        errors.push(`outcome_events contains duplicate id: ${id}`);
      } else {
        seen.add(id);
      }
      if (!allowedTypes.has(event.type)) {
        errors.push(`outcome_events[${index}].type is invalid`);
      }
      if (
        typeof event.at !== "string" ||
        !Number.isFinite(Date.parse(event.at))
      ) {
        errors.push(`outcome_events[${index}].at is invalid`);
      }
      for (const field of ["previous_outcome", "corrected_outcome"]) {
        if (
          event[field] !== undefined &&
          !["", "no_response", "replied", "interview", "offer", "rejected"].includes(
            event[field]
          )
        ) {
          errors.push(`outcome_events[${index}].${field} is invalid`);
        }
      }
    }
  }
  for (const field of schema?.timestamp_fields ?? []) {
    const value = record?.[field];
    if (value === "" || value === undefined || value === null) continue;
    if (typeof value !== "string" || !Number.isFinite(Date.parse(value))) {
      errors.push(`${field} must be a valid timestamp`);
    }
  }
  const canonicalUrl = normalizeCanonicalUrl(record?.canonical_url);
  const expectedIdentity = canonicalJobId(record ?? {});
  if (!canonicalUrl) errors.push("canonical_url is invalid");
  if (!String(record?.source_job_id || "").trim()) {
    errors.push("source_job_id is required");
  }
  if (!expectedIdentity || record?.canonical_job_id !== expectedIdentity) {
    errors.push("canonical_job_id does not match the canonical source identity");
  }
  const allowedActions =
    schema?.actions_by_status?.[record?.pipeline_status] ?? [];
  if (!allowedActions.includes(record?.user_action ?? "")) {
    errors.push("user_action is not supported for pipeline_status");
  }
  return errors;
}

function applyValidatedRecordUpdate(record, updates, schema) {
  const candidate = { ...record, ...updates };
  const errors = validateRecordContract(candidate, schema);
  if (errors.length > 0) {
    throw new Error(`Invalid record update: ${errors.join("; ")}`);
  }
  return candidate;
}

function validatePipelineSchema(schema) {
  const errors = [];
  if (schema?.schema_version !== 2) errors.push("schema_version must be 2");
  if (!Array.isArray(schema?.fields) || schema.fields.length === 0) errors.push("fields are required");
  if (!Array.isArray(schema?.pipeline_statuses) || schema.pipeline_statuses.length === 0) {
    errors.push("pipeline_statuses are required");
  }
  const duplicateFields = schema?.fields?.filter((field, index, all) => all.indexOf(field) !== index) ?? [];
  if (duplicateFields.length > 0) errors.push(`duplicate fields: ${[...new Set(duplicateFields)].join(", ")}`);
  const fields = new Set(schema?.fields ?? []);
  for (const collection of ["string_list_fields", "json_array_fields", "timestamp_fields"]) {
    if (!Array.isArray(schema?.[collection])) {
      errors.push(`${collection} must be an array`);
      continue;
    }
    for (const field of schema[collection]) {
      if (!fields.has(field)) errors.push(`${collection} references unknown field: ${field}`);
    }
  }
  for (const [field, rule] of Object.entries(schema?.field_rules ?? {})) {
    if (!fields.has(field)) errors.push(`field rule references unknown field: ${field}`);
    if (!["number", "integer", "enum", "string"].includes(rule?.type)) {
      errors.push(`field rule has unsupported type for ${field}`);
    }
    if (rule?.type === "enum" && (!Array.isArray(rule.values) || rule.values.length === 0)) {
      errors.push(`enum field rule requires values for ${field}`);
    }
    if (rule?.type === "string" && rule.pattern) {
      try {
        new RegExp(rule.pattern);
      } catch {
        errors.push(`string field rule has invalid pattern for ${field}`);
      }
    }
  }

  const statuses = new Set(schema?.pipeline_statuses ?? []);
  const businessResults = new Set(schema?.business_results ?? []);
  const operationalConditions = new Set(schema?.operational_conditions ?? []);
  if (businessResults.size !== 3 ||
      !["ready_to_apply", "review_needed", "skip"].every((status) => businessResults.has(status))) {
    errors.push("business_results must contain only ready_to_apply, review_needed, and skip");
  }
  if ([...businessResults].some((status) => operationalConditions.has(status))) {
    errors.push("business results and operational conditions must be disjoint");
  }
  if (
    [...businessResults, ...operationalConditions].some(
      (status) => !statuses.has(status)
    ) ||
    statuses.size !== businessResults.size + operationalConditions.size
  ) {
    errors.push("pipeline_statuses must be exactly the business results and operational conditions");
  }
  const actions = new Set(schema?.user_actions ?? []);
  if (
    actions.size !== 5 ||
    !["", "I Applied", "Skip", "Approve", "Deny"].every((action) =>
      actions.has(action)
    )
  ) {
    errors.push("user_actions must contain only the supported operator actions");
  }
  for (const [from, destinations] of Object.entries(schema?.transitions ?? {})) {
    if (!statuses.has(from)) errors.push(`transition source is not a status: ${from}`);
    for (const to of destinations) {
      if (!statuses.has(to)) errors.push(`transition destination is not a status: ${to}`);
    }
  }
  for (const status of statuses) {
    if (!(status in (schema?.transitions ?? {}))) errors.push(`missing transitions for status: ${status}`);
    const supportedActions = schema?.actions_by_status?.[status];
    if (!Array.isArray(supportedActions) || supportedActions.length === 0) {
      errors.push(`missing actions_by_status for status: ${status}`);
    } else if (supportedActions.some((action) => !actions.has(action))) {
      errors.push(`actions_by_status contains an unsupported action for status: ${status}`);
    }
  }
  return errors;
}

function validateUniqueIdentityAcrossStores(stores, schema, now = new Date().toISOString()) {
  const errors = [];
  const identities = new Map();
  for (const [store, rows] of Object.entries(stores ?? {})) {
    if (!Array.isArray(rows)) {
      errors.push(`${store} rows must be an array`);
      continue;
    }
    for (const [index, raw] of rows.entries()) {
      const record = normalizeLegacyRecord(raw, schema, now);
      const identity = String(record.canonical_job_id || "")
        .normalize("NFKC")
        .toLocaleLowerCase("en-US");
      if (!identity) {
        errors.push(`${store} row ${index + 2} has invalid identity`);
        continue;
      }
      const previous = identities.get(identity);
      if (previous) {
        errors.push(
          `duplicate canonical identity at ${previous.store} row ${previous.row} and ${store} row ${index + 2}`
        );
      } else {
        identities.set(identity, { store, row: index + 2 });
      }
    }
  }
  return errors;
}

function canTransition(schema, from, to) {
  return (schema.transitions?.[from] ?? []).includes(to);
}

function transitionRecord(record, to, schema, now = new Date().toISOString()) {
  const from = record.pipeline_status;
  if (!canTransition(schema, from, to)) {
    throw new Error(`Invalid pipeline transition: ${from} -> ${to}`);
  }
  const next = {
    ...record,
    pipeline_status: to,
    updated_at: now
  };
  return { ...next, state_guard: stateGuard(next) };
}

function isStaleClaim(record, nowMs, leaseMs) {
  if (!record.processing_token || !record.processing_started_at) return true;
  const startedAt = Date.parse(record.processing_started_at);
  return !Number.isFinite(startedAt) || nowMs - startedAt >= leaseMs;
}

function processingCommitGuard(token) {
  const value = String(token || "").trim();
  return value ? `commit:${value}` : "";
}

function claimRecord(record, { stage, token, now, leaseMs }) {
  const nowMs = Date.parse(now);
  if (!stage || !token || !Number.isFinite(nowMs) || !Number.isFinite(leaseMs) || leaseMs < 1) {
    throw new Error("stage, token, valid now, and positive leaseMs are required");
  }
  if (record.processing_token && !isStaleClaim(record, nowMs, leaseMs)) {
    return { claimed: false, record };
  }
  return {
    claimed: true,
    record: {
      ...record,
      processing_stage: stage,
      processing_token: token,
      processing_commit_guard: processingCommitGuard(token),
      processing_started_at: now,
      updated_at: now
    }
  };
}

function releaseClaim(record, token, now = new Date().toISOString()) {
  if (record.processing_token && record.processing_token !== token) {
    throw new Error("processing token mismatch");
  }
  const next = {
    ...record,
    processing_stage: "",
    processing_token: "",
    processing_started_at: "",
    updated_at: now
  };
  return { ...next, state_guard: stateGuard(next) };
}

function createProcessingClaim(record, executionId, now, leaseMs) {
  const token = `${executionId}:${record.canonical_job_id}:${record.work_stage}`;
  return {
    canonical_job_id: record.canonical_job_id,
    processing_stage: record.work_stage,
    processing_token: token,
    created_at: now,
    expires_at: new Date(Date.parse(now) + leaseMs).toISOString()
  };
}

function chooseWinningClaims(proposedRecords, allClaims, now = new Date().toISOString()) {
  const claimKey = (record) =>
    `${String(record?.canonical_job_id || "")
      .trim()
      .normalize("NFKC")
      .toLocaleLowerCase("en-US")}:${String(
      record?.processing_stage || record?.work_stage || ""
    ).trim()}`;
  const nowMs = Date.parse(now);
  const expectedLeaseMsByKey = new Map();
  for (const record of proposedRecords) {
    const claimCreatedAt = Date.parse(
      record?.claim_created_at ?? record?.created_at
    );
    const claimExpiresAt = Date.parse(
      record?.claim_expires_at ?? record?.expires_at
    );
    const leaseMs = claimExpiresAt - claimCreatedAt;
    if (Number.isFinite(leaseMs) && leaseMs > 0) {
      expectedLeaseMsByKey.set(claimKey(record), leaseMs);
    }
  }
  const rowNumberCounts = new Map();
  for (const claim of allClaims) {
    const rowNumber = Number(claim?.row_number);
    if (!Number.isInteger(rowNumber) || rowNumber < 2) continue;
    rowNumberCounts.set(
      rowNumber,
      (rowNumberCounts.get(rowNumber) || 0) + 1
    );
  }
  const validClaims = allClaims.filter((claim) => {
    const createdAt = Date.parse(claim.created_at);
    const expiresAt = Date.parse(claim.expires_at);
    const rowNumber = Number(claim.row_number);
    const expectedLeaseMs = expectedLeaseMsByKey.get(claimKey(claim));
    return (
      claim.canonical_job_id &&
      claim.processing_stage &&
      claim.processing_token &&
      Number.isFinite(createdAt) &&
      Number.isFinite(expiresAt) &&
      createdAt <= nowMs &&
      expiresAt > createdAt &&
      expiresAt > nowMs &&
      (!Number.isFinite(expectedLeaseMs) ||
        expiresAt - createdAt <= expectedLeaseMs) &&
      Number.isInteger(rowNumber) &&
      rowNumber >= 2 &&
      rowNumberCounts.get(rowNumber) === 1
    );
  });
  const winners = new Map();
  for (const claim of validClaims) {
    const key = claimKey(claim);
    const current = winners.get(key);
    const claimRow = Number(claim.row_number);
    if (!current || claimRow < Number(current.row_number)) {
      winners.set(key, claim);
    }
  }
  const emitted = new Set();
  return proposedRecords.filter((record) => {
    const key = claimKey(record);
    if (
      emitted.has(key) ||
      winners.get(key)?.processing_token !== record.processing_token
    ) {
      return false;
    }
    emitted.add(key);
    return true;
  });
}


const WINDOW_MS = 24 * 60 * 60 * 1000;

function decodeHtml(value = "") {
  const named = {
    amp: "&",
    apos: "'",
    gt: ">",
    lt: "<",
    nbsp: " ",
    quot: "\"",
    "#039": "'",
    "#8211": "–",
    "#8212": "—",
    "#8230": "…"
  };
  return String(value)
    .replace(/&#x([0-9a-f]+);/gi, (_, hex) =>
      String.fromCodePoint(Number.parseInt(hex, 16))
    )
    .replace(/&#(\d+);/g, (_, decimal) =>
      String.fromCodePoint(Number.parseInt(decimal, 10))
    )
    .replace(
      /&([a-z]+|#\d+);/gi,
      (entity, name) => named[name.toLowerCase()] ?? entity
    );
}

function textFromHtml(value = "") {
  return decodeHtml(
    String(value)
      .replace(/<br\s*\/?>/gi, "\n")
      .replace(/<[^>]+>/g, " ")
  )
    .replace(/\s+/g, " ")
    .trim();
}

function parsePostedAt(value) {
  const input = String(value || "").trim();
  if (!input) return "";
  const normalized = input.includes("T")
    ? input
    : `${input.replace(" ", "T")}+08:00`;
  const timestamp = Date.parse(normalized);
  return Number.isFinite(timestamp) ? new Date(timestamp).toISOString() : "";
}

function createDiscoveryWindow(now = new Date().toISOString()) {
  const windowEndMs = Date.parse(now);
  if (!Number.isFinite(windowEndMs)) {
    throw new Error("Discovery window requires a valid execution timestamp");
  }
  return Object.freeze({
    window_start: new Date(windowEndMs - WINDOW_MS).toISOString(),
    window_end: new Date(windowEndMs).toISOString(),
    window_hours: 24
  });
}

function validateSearchPlan(plan) {
  const errors = [];
  if (plan?.schema_version !== 2) {
    errors.push("search plan schema_version must be 2");
  }
  if (!/^\d{4}-\d{2}-\d{2}\/v\d+$/.test(plan?.plan_version || "")) {
    errors.push("search plan plan_version must use YYYY-MM-DD/vN");
  }
  if (plan?.source !== "onlinejobs.ph") {
    errors.push("search plan source must be onlinejobs.ph");
  }
  if (plan?.window_hours !== 24) {
    errors.push("window_hours must be exactly 24");
  }
  if (plan?.pagination_mode !== "adaptive_source_exhaustion") {
    errors.push("pagination_mode must be adaptive_source_exhaustion");
  }
  for (const field of [
    "schedule_minutes",
    "execution_timeout_seconds",
    "page_size",
    "max_pages_per_keyword",
    "request_interval_ms",
    "request_timeout_ms",
    "claim_lease_ms"
  ]) {
    if (!Number.isInteger(plan?.[field]) || plan[field] < 1) {
      errors.push(`${field} must be a positive integer`);
    }
  }
  if (
    Number.isInteger(plan?.execution_timeout_seconds) &&
    Number.isInteger(plan?.schedule_minutes) &&
    plan.execution_timeout_seconds >= plan.schedule_minutes * 60
  ) {
    errors.push("execution timeout must be shorter than the discovery schedule");
  }
  if (
    Number.isInteger(plan?.request_timeout_ms) &&
    Number.isInteger(plan?.execution_timeout_seconds) &&
    plan.request_timeout_ms >= plan.execution_timeout_seconds * 1000
  ) {
    errors.push("request timeout must be shorter than execution timeout");
  }
  errors.push(...validateMinuteIntervalSchedule(plan, "discovery"));

  if (!Array.isArray(plan?.keywords) || plan.keywords.length === 0) {
    errors.push("at least one keyword is required");
    return errors;
  }
  const ids = new Set();
  const values = new Set();
  for (const entry of plan.keywords) {
    const id = String(entry?.id || "").trim();
    const keyword = String(entry?.keyword || "").trim();
    if (!id || !keyword || typeof entry?.enabled !== "boolean") {
      errors.push("every keyword requires id, keyword, and enabled");
      continue;
    }
    const normalized = keyword.normalize("NFKC").toLocaleLowerCase("en-US");
    if (ids.has(id)) errors.push(`duplicate keyword id: ${id}`);
    if (values.has(normalized)) errors.push(`duplicate keyword: ${keyword}`);
    ids.add(id);
    values.add(normalized);
    if ("evidence_refs" in entry || "role_family" in entry) {
      errors.push(`keyword ${id} must not contain resume or adjacent-role metadata`);
    }
  }
  if (!plan.keywords.some((entry) => entry.enabled)) {
    errors.push("at least one keyword must be enabled");
  }
  return errors;
}

function searchRequest(keyword, pageNumber, plan, window) {
  const offset = (pageNumber - 1) * plan.page_size;
  const path =
    pageNumber === 1
      ? "/jobseekers/jobsearch"
      : `/jobseekers/jobsearch/${offset}`;
  return {
    keyword_id: keyword.id,
    keyword: keyword.keyword,
    page_number: pageNumber,
    request_url:
      `https://www.onlinejobs.ph${path}?jobkeyword=` +
      encodeURIComponent(keyword.keyword),
    window_start: window.window_start,
    window_end: window.window_end
  };
}

function buildSearchRequests(
  plan,
  window = createDiscoveryWindow()
) {
  return plan.keywords
    .filter((entry) => entry.enabled)
    .map((keyword) => searchRequest(keyword, 1, plan, window));
}

function sourceResultCardCount(page) {
  if (Number.isInteger(page?.result_card_count) && page.result_card_count >= 0) {
    return page.result_card_count;
  }
  return ["jobs", "excluded", "malformed"].reduce(
    (total, field) =>
      total + (Array.isArray(page?.[field]) ? page[field].length : 0),
    0
  );
}

function sourcePageExhausted(page) {
  return Boolean(page?.ok && !page.has_next);
}

function buildNextSearchRequest(page, plan) {
  if (
    !page?.ok ||
    sourcePageExhausted(page) ||
    !Number.isInteger(page.page_number) ||
    page.page_number < 1 ||
    page.page_number >= plan.max_pages_per_keyword
  ) {
    return null;
  }
  return searchRequest(
    { id: page.keyword_id, keyword: page.keyword },
    page.page_number + 1,
    plan,
    {
      window_start: page.window_start,
      window_end: page.window_end
    }
  );
}

function advanceSearchPagination(state, page, plan) {
  if (
    state?.window_start &&
    (state.window_start !== page?.window_start ||
      state.window_end !== page?.window_end)
  ) {
    throw new Error("Discovery page changed the immutable execution window");
  }
  const nextRequest = buildNextSearchRequest(page, plan);
  return {
    ...state,
    ...(nextRequest || {}),
    page_results: [
      ...(Array.isArray(state?.page_results) ? state.page_results : []),
      page
    ],
    fetch_next_page: Boolean(nextRequest)
  };
}

function parseSearchResults(html, request) {
  const jobs = [];
  const excluded = [];
  const malformed = [];
  const windowStartMs = Date.parse(request?.window_start || "");
  const windowEndMs = Date.parse(request?.window_end || "");
  if (
    !Number.isFinite(windowStartMs) ||
    !Number.isFinite(windowEndMs) ||
    windowEndMs - windowStartMs !== WINDOW_MS
  ) {
    throw new Error("Search parsing requires one valid fixed 24-hour window");
  }

  const pageText = String(html || "");
  const cardRegex =
    /<a\s+href=["'](\/jobseekers\/job\/[^"']+)["'][^>]*>\s*<div[^>]*class=["'][^"']*jobpost-cat-box[^"']*["'][^>]*>([\s\S]*?)<\/div>\s*<\/a>/gi;
  let resultCardCount = 0;
  let match;
  while ((match = cardRegex.exec(pageText)) !== null) {
    resultCardCount += 1;
    const urlPath = match[1];
    const cardHtml = match[2];
    const titleMatch = cardHtml.match(/<h4[^>]*>([\s\S]*?)<\/h4>/i);
    const dateMatch =
      cardHtml.match(/data-temp=["']([^"']+)["']/i) ||
      cardHtml.match(/<em>\s*Posted on\s+([^<]+)<\/em>/i);
    if (!titleMatch) {
      malformed.push({ url_path: urlPath, reason: "missing_title" });
      continue;
    }
    if (!dateMatch) {
      malformed.push({ url_path: urlPath, reason: "missing_posted_at" });
      continue;
    }

    const title = textFromHtml(
      titleMatch[1].replace(
        /<span[^>]*class=["'][^"']*badge[^"']*["'][^>]*>[\s\S]*?<\/span>/gi,
        ""
      )
    );
    const postedAt = parsePostedAt(dateMatch[1]);
    if (!title) {
      malformed.push({ url_path: urlPath, reason: "empty_title" });
      continue;
    }
    if (!postedAt) {
      malformed.push({ url_path: urlPath, reason: "invalid_posted_at" });
      continue;
    }
    const postedAtMs = Date.parse(postedAt);
    if (postedAtMs < windowStartMs) {
      excluded.push({
        url_path: urlPath,
        posted_at: postedAt,
        reason: "outside_window_old"
      });
      continue;
    }
    if (postedAtMs > windowEndMs) {
      excluded.push({
        url_path: urlPath,
        posted_at: postedAt,
        reason: "future_dated"
      });
      continue;
    }

    const salaryMatch = cardHtml.match(
      /<dd\s+class=["']col["'][^>]*>([\s\S]*?)<\/dd>/i
    );
    const descriptionMatch = cardHtml.match(
      /<div[^>]*class=["'][^"']*\bdesc\b[^"']*["'][^>]*>([\s\S]*?)<\/div>/i
    );
    const canonicalUrl = normalizeCanonicalUrl(urlPath);
    const job = {
      source: "onlinejobs.ph",
      source_job_id: extractOnlineJobsId(canonicalUrl),
      canonical_url: canonicalUrl,
      job_title: title,
      company: "",
      salary_text: textFromHtml(salaryMatch?.[1] ?? ""),
      search_summary: textFromHtml(descriptionMatch?.[1] ?? ""),
      posted_at: postedAt,
      matched_keywords: [request.keyword],
      source_availability: "active"
    };
    job.canonical_job_id = canonicalJobId(job);
    if (!job.canonical_job_id) {
      malformed.push({ url_path: urlPath, reason: "invalid_identity" });
      continue;
    }
    jobs.push(job);
  }

  const hasNext = /<a[^>]+rel=["']next["'][^>]*>/i.test(pageText);
  const pageNumbers = [
    ...pageText.matchAll(/data-ci-pagination-page=["'](\d+)["']/gi)
  ].map((entry) => Number(entry[1]));
  const reportedLastPage =
    pageNumbers.length > 0 ? Math.max(...pageNumbers) : request.page_number;
  const explicitEmpty =
    /\bno\s+(?:job\s+posts?|jobs?)\s+(?:matched|found|available)\b/i.test(
      textFromHtml(pageText)
    );
  const hasSearchPageEvidence = resultCardCount > 0 || explicitEmpty;
  return {
    ...request,
    ok: hasSearchPageEvidence,
    jobs,
    excluded,
    malformed,
    result_card_count: resultCardCount,
    has_next: hasNext,
    reported_last_page: reportedLastPage,
    ...(hasSearchPageEvidence
      ? {}
      : {
          error_category: "unexpected_search_page",
          error_summary:
            "Search response lacked recognizable result-page evidence."
        })
  };
}

function effectivePagesForKeyword(pages) {
  const sorted = [...pages].sort((left, right) => left.page_number - right.page_number);
  const effective = [];
  for (const page of sorted) {
    effective.push(page);
    if (sourcePageExhausted(page)) break;
  }
  return effective;
}

function summarizeCoverage(pageResults, plan) {
  const keywords = [];
  for (const keyword of plan.keywords.filter((entry) => entry.enabled)) {
    const pages = effectivePagesForKeyword(
      pageResults.filter((result) => result.keyword_id === keyword.id)
    );
    const successes = pages.filter((page) => page.ok);
    const failures = pages.filter((page) => !page.ok);
    const lastSuccess = successes.at(-1);
    let status = "failed";
    let stopReason = failures.length > 0 ? "request_failure" : "no_page_result";
    if (successes.length > 0 && failures.length > 0) {
      status = "partial";
    } else if (
      successes.length > 0 &&
      sourceResultCardCount(successes[0]) === 0 &&
      sourcePageExhausted(successes[0])
    ) {
      status = "empty";
      stopReason = "no_results";
    } else if (lastSuccess && sourcePageExhausted(lastSuccess)) {
      status = "complete";
      stopReason = "source_exhausted";
    } else if (
      lastSuccess?.page_number >= plan.max_pages_per_keyword
    ) {
      status = "partial";
      stopReason = "page_limit";
    } else if (successes.length > 0) {
      status = "partial";
      stopReason = "incomplete_pages";
    }
    keywords.push({
      keyword_id: keyword.id,
      keyword: keyword.keyword,
      status,
      stop_reason: stopReason,
      pages_succeeded: successes.length,
      pages_failed: failures.length,
      result_cards_seen: successes.reduce(
        (total, page) => total + sourceResultCardCount(page),
        0
      ),
      jobs_found: successes.reduce(
        (total, page) => total + page.jobs.length,
        0
      ),
      malformed_count: successes.reduce(
        (total, page) => total + page.malformed.length,
        0
      ),
      excluded_count: successes.reduce(
        (total, page) => total + page.excluded.length,
        0
      )
    });
  }
  return {
    status: keywords.some(
      (entry) => entry.status === "failed" || entry.status === "partial"
    )
      ? "partial"
      : keywords.every((entry) => entry.status === "empty")
        ? "empty"
        : "complete",
    pages_requested: keywords.reduce(
      (total, entry) => total + entry.pages_succeeded + entry.pages_failed,
      0
    ),
    maximum_page_requests:
      plan.keywords.filter((entry) => entry.enabled).length *
      plan.max_pages_per_keyword,
    keywords
  };
}

function unionValues(...collections) {
  return [
    ...new Set(
      collections
        .flat()
        .filter(Boolean)
        .map((value) => String(value).trim())
    )
  ];
}

function identityKey(value) {
  return String(value || "")
    .trim()
    .normalize("NFKC")
    .toLocaleLowerCase("en-US");
}

function reconcileDiscovery(
  pageResults,
  reviewRows,
  appliedRows,
  archiveRows,
  schema,
  now = new Date().toISOString()
) {
  const identityErrors = validateUniqueIdentityAcrossStores(
    {
      "Review Queue": reviewRows,
      "Applied Jobs": appliedRows,
      Archive: archiveRows
    },
    schema,
    now
  );
  if (identityErrors.length > 0) {
    throw new Error(`Discovery store identity check failed: ${identityErrors.join("; ")}`);
  }

  const existing = new Map();
  for (const [location, rows] of [
    ["review", reviewRows],
    ["applied", appliedRows],
    ["archive", archiveRows]
  ]) {
    for (const raw of rows) {
      const normalized = normalizeLegacyRecord(raw, schema, now);
      const entry = { location, raw, normalized };
      existing.set(identityKey(normalized.canonical_job_id), entry);
      existing.set(`url:${identityKey(normalized.canonical_url)}`, entry);
    }
  }

  const discovered = new Map();
  let malformedCount = 0;
  const exclusionCounts = {};
  for (const page of pageResults.filter((result) => result.ok)) {
    malformedCount += page.malformed.length;
    for (const excluded of page.excluded) {
      exclusionCounts[excluded.reason] =
        (exclusionCounts[excluded.reason] || 0) + 1;
    }
    for (const job of page.jobs) {
      const key = identityKey(job.canonical_job_id);
      const current = discovered.get(key);
      if (current) {
        current.matched_keywords = unionValues(
          current.matched_keywords,
          job.matched_keywords
        );
      } else {
        discovered.set(key, {
          ...job,
          matched_keywords: [...job.matched_keywords]
        });
      }
    }
  }

  const newJobs = [];
  const reviewUpdates = [];
  let terminalSuppressed = 0;
  for (const job of discovered.values()) {
    const match =
      existing.get(identityKey(job.canonical_job_id)) ||
      existing.get(`url:${identityKey(job.canonical_url)}`);
    if (match?.location === "review") {
      const updated = {
        ...match.normalized,
        row_number: match.raw.row_number,
        source_job_id: job.source_job_id,
        canonical_job_id: job.canonical_job_id,
        canonical_url: job.canonical_url,
        matched_keywords: unionValues(
          match.normalized.matched_keywords,
          job.matched_keywords
        ),
        last_seen_at: now,
        updated_at: now
      };
      reviewUpdates.push(updated);
      continue;
    }
    if (match) {
      terminalSuppressed += 1;
      continue;
    }
    const record = normalizeLegacyRecord(
      {
        ...job,
        pipeline_status: "new",
        user_action: "",
        record_version: 1,
        discovered_at: now,
        last_seen_at: now,
        created_at: now,
        updated_at: now,
        attempt_count: 0,
        alert_attempt_count: 0,
        outcome: ""
      },
      schema,
      now
    );
    record.state_guard = stateGuard(record);
    newJobs.push(record);
  }

  return {
    new_jobs: newJobs,
    review_updates: reviewUpdates,
    discovered_unique: discovered.size,
    terminal_suppressed: terminalSuppressed,
    malformed_count: malformedCount,
    exclusion_counts: exclusionCounts
  };
}

